'use client';

import { signIn, signOut, useSession } from 'next-auth/react';
import { LogIn, LogOut, Cloud, CloudOff } from 'lucide-react';

export default function GoogleSignIn() {
  const { data: session, status } = useSession();

  if (status === 'loading') {
    return (
      <div className="flex items-center gap-2 text-gray-400 text-sm">
        <div className="w-4 h-4 border-2 border-gray-400 border-t-transparent rounded-full animate-spin" />
        <span>Loading...</span>
      </div>
    );
  }

  if (session) {
    return (
      <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
        <div className="flex items-center gap-3">
          <img
            src={session.user.image || ''}
            alt={session.user.name || 'User'}
            className="w-10 h-10 rounded-full border-2 border-yellow-400"
          />
          <div className="flex flex-col">
            <span className="text-white text-sm font-medium">
              {session.user.name}
            </span>
            <div className="flex items-center gap-1.5 text-green-400 text-xs">
              <Cloud className="w-3.5 h-3.5" />
              <span>Synced to Google Drive</span>
            </div>
          </div>
        </div>
        <button
          onClick={() => signOut()}
          className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 hover:border-white/20 text-white text-sm rounded-lg transition-all duration-200"
          data-testid="button-sign-out"
        >
          <LogOut className="w-4 h-4" />
          <span>Sign Out</span>
        </button>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-3">
      <button
        onClick={() => signIn('google')}
        className="flex items-center justify-center gap-3 px-6 py-3 bg-white text-gray-900 hover:bg-gray-100 rounded-lg font-medium transition-all duration-200 shadow-lg hover:shadow-xl"
        data-testid="button-sign-in-google"
      >
        <svg className="w-5 h-5" viewBox="0 0 24 24">
          <path
            fill="#4285F4"
            d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
          />
          <path
            fill="#34A853"
            d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
          />
          <path
            fill="#FBBC05"
            d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
          />
          <path
            fill="#EA4335"
            d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
          />
        </svg>
        <span>Sign in with Google</span>
      </button>
      <div className="flex items-start gap-2 text-gray-400 text-xs">
        <CloudOff className="w-4 h-4 mt-0.5 flex-shrink-0" />
        <span>
          Sign in to sync your watchlist and favorites across all devices using your Google Drive
        </span>
      </div>
    </div>
  );
}
